NAME = 'Est: Estonian Bible'
BOOK = 'Romans'

CHAPTERS = {
    1: {
        1: 'Paulus, Jeesuse Kristuse sulane, kutsutud Apostliks, välja valitud kuulutama Jumala Evangeeliumi,',
        2: 'mille Jumal on enne tõotanud Oma prohvetite kaudu pühades kirjades',
        3: 'Oma Pojast - Kes liha poolest on sündinud Taaveti soost',
        4: 'ja pühaduse vaimu poolest on seatud surnuist ülestõusmise läbi Jumala Pojaks väes - Jeesusest Kristusest, meie Issandast,',
        5: 'Kelle läbi me oleme saanud armu ja apostliameti, et äratada usu sõnakuulelikkust Tema nime heaks kõigi rahvaste seas,',
        6: 'kelle seast ka teie olete Jeesuse Kristuse poolt kutsutud,',
        7: 'kõigile Roomas olevaile Jumala armastatuile, kutsutud pühadele: armu teile ja rahu Jumalalt, meie Isalt, ja Issandalt Jeesuselt Kristuselt.',
        8: 'Kõigepealt ma tänan oma Jumalat Jeesuse Kristuse läbi teie kõikide pärast, et teie usust kiitvalt kõneldakse kogu maailmas.',
        9: 'Sest Jumal, Keda ma oma vaimus teenin Tema Poja Evangeeliumi kuulutamisega, on mu tunnistaja, kuidas ma lakkamata pean teid meeles,',
        10: 'aina oma palvetes anudes, kas ma juba kord Jumala tahtmisel saaksin tulla teie juurde.',
        11: 'Sest ma igatsen teid näha, et võiksin jagada teile pisut vaimulikku annet teie kinnituseks;',
        12: 'see on, et me teie juures üheskoos olles vastastikku ergutaksime üksteist ühise usu, teie ja minu oma läbi.',
        13: 'Ja ma ei taha, vennad, et teil oleks teadmata, et ma sageli olen ette võtnud tulla teie juurde, et ma ka teie seas võiksin saata mõnd kasu, nõnda nagu muude paganate seas; aga ma olin tänini takistatud.',
        14: 'Ma olen nii kreeklaste kui umbkeelsete, nii tarkade kui rumalate võlglane;',
        15: 'siis olen ma omalt poolt valmis ka teile, Roomas asuvaile, Evangeeliumi kuulutama.',
        16: 'Sest ma ei häbene Evangeeliumi; sest see on Jumala vägi õndsakssaamiseks igaühele, kes usub, nii juudile esiti kui ka kreeklasele.',
        17: 'Sest temas saab ilmsiks Jumala õigus usust usku, nõnda nagu on kirjutatud: "Õige elab usust!"',
        18: 'Sest Jumala viha saab ilmsiks taevast kõige inimeste jumalatuse ja ülekohtu vastu, nende vastu, kes tõde ülekohtuga kinni peavad,',
        19: 'sellepärast et see, mida teatakse Jumalast, on avalik nende seas; sest Jumal on seda neile avaldanud.',
        20: 'Sest Tema nähtamatut olu, nii Tema igavest väge kui jumalikku olemist, nähakse, kui neid pannakse tähele, Tema tegudes maailma loomisest alates, nii et nad ei saa vabanduda,',
        21: 'sellepärast et nad Jumalat tundes ei ole teda kui Jumalat austanud ega tänanud, vaid on oma mõtlemistes saanud tühiseks ja nende mõistmatu süda on läinud pimedaks.',
        22: 'Kiites endid targaks, on nad saanud jõledaks',
        23: 'ja on kadumatu Jumala au vahetanud kaduva inimese ja lindude ja neljajalgsete ja roomajate sarnase kuju vastu.',
        24: 'Sellepärast on Jumal nad andnudki nende südamete himudes rüvedusse, oma ihusid ise pilastama.',
        25: 'Nemad on Jumala tõe vahetanud vale vastu ja on austanud ning teeninud loodut enam kui Loojat, Kes on ülistatud igavesti. Aamen.',
        26: 'Sellepärast on Jumal nad andnud häbematuisse ihadesse; sest nende naised on vahetanud loomuliku sugulise käitlemise loomuvastasega,',
        27: 'ja samuti on ka mehed loobunud loomulikust naise sugulisest käitlemisest ja on oma himus süttinud üksteisest ja teinud rõvedust mees mehega ja kätte saanud iseenestes oma eksimuse palga, mille pidid saama.',
        28: 'Ja nagu nad heaks ei arvanud kinni pidada Jumala tunnetamisest, nii on Jumal nad andnud hoolimatu meele sisse, tegema seda, mis ei kõlba;',
        29: 'nad on täis kõike ülekohut, kurjust, ahnust, tigedust, täis kadedust, mõrva, riidu, kurikavalust; nad on keelekandjad,',
        30: 'laimajad, Jumala vihkajad, ülbed, suurelised, hooplejad, leidlikud kurjale, sõnakuulmatud vanemaile,',
        31: 'mõistmatud, lepingu rikkujad, armuheitmatud, halastamatud,',
        32: 'kes, ehk nad küll tunnevad Jumala õiguse määrust ja teavad, et need, kes teevad niisuguseid asju, on surma väärt, ei tee mitte ainult sedasama, vaid tunnevad head meelt neist, kes nõnda teevad.',
    },
    2: {
        1: 'Sellepärast, oh inimene, kes kohut mõistad, ole sa kes tahes, ei ole sul mingit vabandust! Sest milles sa kohut mõistad teise üle, sessamas sa mõistad iseenese hukka; sest sina, kes teist hukka mõistad, teed ise sedasama!',
        2: 'Aga me teame, et Jumala kohus tõepoolest tabab neid, kes sellesarnast teevad.',
        3: 'Või mõtled sa, oh inimene, kes kohut mõistad nende üle, kes sellesarnast teevad, ja teed ka sedasama, et sa pääsed Jumala kohtu eest?',
        4: 'Või põlgad sa Tema helduse ja kannatlikkuse ja pika meele rohkust ega saa aru, et Jumala heldus sind ajab meelt parandama?',
        5: 'Ent sa kogud enesele viha oma kangusega ja patustpöördumata südamega vihapäevaks ja Jumala õige kohtu ilmumiseks,',
        6: 'Kes igaühele maksab tema tegude järgi,',
        7: 'neile küll igavest elu, kes head tehes püsivusega otsivad au ja kiitust ja kadumatut põlve,',
        8: 'aga neile, kes on riiakad ja tõele sõnakuulmatud, aga sõnakuulelikud ülekohtule, viha ja raevu!',
        9: 'Viletsus ning ahastus tuleb igale inimese hingele, kes kurja teeb, nii juudile esiti kui ka kreeklasele,',
        10: 'aga au ja kiitus ja rahu igaühele, kes head teeb, nii juudile esiti kui ka kreeklasele!',
        11: 'Sest Jumal ei tee vahet isikute vahel!',
        12: 'Sest kõik, kes ilma käsuta on pattu teinud, lähevad ka hukka ilma käsuta; ja kõik, kes käsu all on pattu teinud, nende üle mõistetakse ka kohut käsu järgi;',
        13: 'sest käsu kuuljad ei ole õiged Jumala ees, vaid käsu tegijad mõistetakse õigeks -',
        14: 'sest kui paganad, kellel ei ole käsku, loomu poolest täidavad käsu nõudeid, on nad, ehk küll neil ei ole käsku, iseenestele käsuks',
        15: 'ja näitavad, et käsutegu on kirjutatud nende südametesse, kuna nende südametunnistus ühtlasi tunnistab seda ja nende mõtted isekeskis kas kaebavad nende peale või ka kostavad nende eest',
        16: '- sel päeval, kui Jumal kohut mõistab inimeste salajaste asjade üle Kristuse Jeesuse läbi minu Evangeeliumi järgi.',
        17: 'Ent kui sa nimetad ennast juudiks ja loodad käsu peale ning kiitled Jumalast',
        18: 'ja tunned Tema tahtmist, ja käsust õpetust saades katsud läbi, mis on kõige parem,',
        19: 'ja pead ennast sõgedate teejuhiks, nende valguseks, kes on pimeduses,',
        20: 'mõistmatute juhatajaks, alaealiste õpetajaks, kellel on käes täieks kujunenud tunnetus ja tõde käsuõpetuses;',
        21: 'kuidas sa siis, kes teist õpetad, iseennast ei õpeta; kes kuulutad, et ei tohi varastada, ise varastad;',
        22: 'kes ütled, et ei tohi abielu rikkuda, ise rikud abielu; kes pead ebajumalaid jäledaks asjaks, ise riisud pühamut;',
        23: 'kes kiitled käsust, ise teotad Jumalat käsust üleastumisega?',
        24: 'Pilgatakse ju Jumala nime teie pärast paganate seas, nõnda nagu on kirjutatud.',
        25: 'Sest ümberlõikamisest on küll kasu, kui sa teed käsu järgi; aga kui sa oled käsust üleastuja, siis on sinu ümberlõikamine saanud eesnahaks.',
        26: 'Kui nüüd ümberlõikamatu peab käsu nõudmisi, eks siis tema eesnahka peeta ümberlõikamiseks?',
        27: 'Ja eks siis see, kes loomu poolest on ümberlõikamatu ja peab täiesti käsku, mõista kohut sinu üle, kes kirjatähe ja ümberlõikamise kaudu oled ometi käsust üleastuja?',
        28: 'Ei ole ju juut see, kes seda on välispidi; ega ole ümberlõikamine see, mis sünnib välispidi lihas,',
        29: 'vaid juut on see, kes seda on seespidi, ja südame ümberlõikamine on vaimus, mitte kirjatähes. Niisugune saab kiituse mitte inimestelt, vaid Jumalalt.',
    },
    3: {
        1: 'Mis paremus on siis juudil? Või mis kasu on ümberlõikamisest?',
        2: 'On paljugi kõikepidi! Kõigepealt see, et nende kätte on usaldatud, mida Jumal on rääkinud.',
        3: 'Mis sellest, kui mõned olid uskmatud? Ega siis nende uskmatu meel tee tühjaks Jumala ustavust?',
        4: 'Mitte sugugi! Kindel on, et Jumal on tõemeelne, olgugi, et iga inimene on valelik, nagu on kirjutatud: "Et Sa oleksid õiglane Oma sõnades ja võit jääks Sinule, kui Sinuga kohtus käiakse!"',
        5: 'Aga kui meie ülekohus teeb avalikuks Jumala õigluse, mis peame siis ütlema? Kas Jumal ei ole ülekohtune, kui Ta nuhtleb vihas? Ma räägin kui inimene.',
        6: 'Mitte sugugi! Kuidas võiks siis Jumal kohut mõista maailma üle?',
        7: 'Sest kui Jumala tõde minu vale läbi saab palju selgemaks Tema auks, miks siis veel minu kui patuse üle kohut mõistetakse?',
        8: 'Ja miks me ei teeks nõnda, nagu meist pilgates öeldakse ja nagu mõned meist räägivad, et meie ütlevat: "Tehkem kurja, et sellest tuleks head?" Niisugune nuhtlus on õige.',
        9: 'Kuidas siis on? Kas me oleme paremas seisukorras? Mitte sugugi! Oleme ju varemini tõestanud, et niihästi juudid kui kreeklased on kõik patu all,',
        10: 'nõnda nagu on kirjutatud: "Ei ole kedagi, kes oleks õige, ei ühtainustki;',
        11: 'ei ole arusaajat; ei ole, kes otsiks Jumalat;',
        12: 'nad kõik on läinud kõrvale, nad on puha saanud kõlvatuks, ei ole kedagi, kes teeb head, ei ühtainustki.',
        13: 'Nende kurk on lahtine haud; oma keelega nad petavad; madude mürk on nende huulte taga.',
        14: 'Nende suu on täis sajatamist ja kibedaid sõnu;',
        15: 'nende jalad on nobedad verd valama;',
        16: 'hävitus ja õnnetus on nende teedel,',
        17: 'ja rahu teed nad ei tunne;',
        18: 'ei ole Jumala kartust nende silmade ees!"',
        19: 'Aga me teame, et mida iganes käsk ütleb, seda ta ütleb neile, kes on käsu all, et iga suu suletaks ja kogu maailm oleks süüalune Jumala ees;',
        20: 'sellepärast et käsu tegudest ei mõisteta õigeks ühtki liha tema ees; sest käsu kaudu tuleb patu tundmine.',
        21: 'Aga nüüd on Jumala õigus, millest käsk ja prohvetid tunnistavad, ilmutatud ilma käsuta,',
        22: 'see Jumala õigus, mis tuleb Jeesuse Kristuse usu kaudu kõikidele, kes usuvad; sest siin ei ole ühtki vahet;',
        23: 'sest kõik on pattu teinud ja on Jumala aust ilma',
        24: 'ning mõistetakse õigeks täiesti muidu, Tema armust, lunastuse läbi, mis on Kristuses Jeesuses,',
        25: 'Kelle Jumal on seadnud lepitusvahendiks usu kaudu Tema veres, Oma õiguse osutamiseks enne tehtud pattude arvestamata jätmise pärast',
        26: 'tol ajal, kui Jumal seda sallis, et osutada Oma õigust praegusel ajal ning näidata, et Tema on õige ja teeb õigeks selle, kes on Jeesuse usust.',
        27: 'Kus on nüüd kiitlemine? See on kõrvaldatud. Missuguse käsu läbi? Kas tegude käsu läbi? Ei mitte, vaid usu käsu läbi.',
        28: 'Sellepärast me arvame, et inimene mõistetakse õigeks usu läbi lahus käsu tegudest.',
        29: 'Või on Jumal ükspäinis juutide Jumal? Eks Ta ole ka paganate Jumal? Jah, tõesti ka paganate Jumal!',
        30: 'Sest üks ja sama Jumal teeb usust õigeks ümberlõigatu ja usu läbi ümberlõikamatu.',
        31: 'Kas me siis teeme käsu tühjaks usu läbi? Mitte sugugi, vaid me kinnitame käsku!',
    },
    4: {
        1: 'Mis me siis ütleme oma lihase esiisa Aabrahami saavutanud olevat?',
        2: 'Sest kui Aabraham on õigeks mõistetud tegudest, on temal kiitlemist, kuid mitte Jumala ees.',
        3: 'Sest mis ütleb Kiri? "Aabraham uskus Jumalat ja see arvati temale õiguseks!"',
        4: 'Aga tegude tegijale ei arvata palka mitte armust, vaid teenet mööda.',
        5: 'Aga kes tegusid ei tee, vaid usub Temasse, Kes mõistab õigeks jumalatu, sellele arvatakse tema usk õiguseks,',
        6: 'nõnda nagu Taavet kiidab õndsaks inimest, kellele Jumal arvab õiguse osaks ilma tegudeta:',
        7: '"Õndsad need, kelle ülekohus on andeks antud ja kelle patud on kinni kaetud.',
        8: 'Õnnis see, kellele Jumal pattu ei arvesta!"',
        9: 'Kas nüüd see õndsakskiitmine käib ainult ümberlõigatute kohta või ka ümberlõikamatute kohta? Me ju ütleme, et Aabrahamile usk arvati õiguseks.',
        10: 'Kuidas see siis arvati? Kas siis, kui ta oli ümberlõigatu või kui ta oli ümberlõikamatu? Mitte kui ta oli ümberlõigatu, vaid kui ta oli ümberlõikamatu.',
        11: 'Ja ümberlõikamise märgi ta sai selle usu õiguse kinnituseks, mis tal oli ümberlõikamata põlves, et ta oleks kõikide isa, kes usuvad ümberlõikamatutena, et õigus arvatakse ka neile osaks',
        12: 'ja et ta oleks ka ümberlõigatute isa, nende isa, kes mitte ainult ei ole ümber lõigatud, vaid ka käivad meie isa Aabrahami usu jälgedes, mis tal oli juba ümberlõikamatuna.',
        13: 'Sest see tõotus, et Aabraham saab maailma pärijaks, ei antud temale ega tema soole mitte käsu läbi, vaid usu õiguse kaudu.',
        14: 'Sest kui need, kes on käsust, on pärijad, siis on usk tühistatud ja tõotus on tehtud mõjutuks.',
        15: 'Sest käsk toob viha; aga kus ei ole käsku, seal ei ole ka üleastumist.',
        16: 'Sellepärast on see usust, et see oleks armust, et tõotus oleks kindel kogu soole, mitte üksnes sellele, mis on pärit käsust, vaid ka sellele, mis on pärit Aabrahami usust, kes on meie kõikide isa -',
        17: 'nagu on kirjutatud: "Ma olen sind pannud paljude rahvaste isaks!" - selle Jumala ees, Keda ta uskus ja Kes teeb elavaks surnud ja kutsub esile olematuid asju otsekui olevaid.',
        18: 'Tema uskus üle lootuse lootuses, et ta saab paljude rahvaste isaks vastavalt sõnale: "Nõnda peab olema sinu sugu!"',
        19: 'Ja ta ei läinud usus nõdraks tähele pannes oma ihu, mis oli elatanud - oli ta ju umbes saja-aastane - ja et Saara lapsekoda oli surnud.',
        20: 'Ent Jumala tõotusest ta ei mõtelnud uskmatuses kaksipidi, vaid sai vägevaks usus, andes Jumalale austust',
        21: 'ja olles täiesti julge selles, et Jumal on vägev tegema, mis Ta on tõotanud.',
        22: 'Sellepärast see arvatigi temale õiguseks.',
        23: 'Aga ei ole mitte üksnes tema pärast kirjutatud, et see arvati temale õiguseks,',
        24: 'vaid ka meie pärast, kellele see peab arvatama õiguseks, sest me usume Temasse, Kes surnuist üles äratas meie Issanda Jeesuse,',
        25: 'Kes loovutati meie üleastumiste pärast ja üles äratati meie õigekssaamise pärast.',
    },
    5: {
        1: 'Et me nüüd oleme usust õigeks saanud, siis on meil rahu Jumalaga meie Issanda Jeesuse Kristuse läbi,',
        2: 'Kelle läbi me oleme ka usus saanud ligipääsu sellele armule, milles me nüüd oleme, ja kiitleme Jumala au lootusest.',
        3: 'Aga mitte üksnes sellest, vaid me kiitleme ka viletsustest, teades, et viletsus saadab kannatlikkuse,',
        4: 'ja kannatlikkus saadab püsivuse ja püsivus lootuse;',
        5: 'aga lootus ei jäta häbisse, sest Jumala armastus on välja valatud meie südameisse Püha Vaimu läbi, Kes meile on antud.',
        6: 'Sest Kristus on, kui me alles nõdrad olime, omal ajal surnud nende eest, kes alles olid jumalatud.',
        7: 'Vaevalt ju keegi läheb surma õige eest; ehk mõni küll julgeks surra hea sõbra eest.',
        8: 'Ent Jumal osutab Oma armastust meie vastu sellega, et Kristus on surnud meie eest, kui me alles patused olime;',
        9: 'kui palju enam me nüüd, olles õigeks saanud Tema veres, pääseme Tema kaudu viha eest.',
        10: 'Sest kui meid Jumalaga lepitati Tema Poja surma kaudu, kui me alles olime Jumala vaenlased, kui palju enam päästetakse meid Tema elu läbi nüüd, kus me juba oleme lepitatud.',
        11: 'Aga mitte ainult seda, vaid me kiitleme ka Jumalast meie Issanda Jeesuse Kristuse läbi, Kelle kaudu me nüüd oleme saanud lepituse.',
        12: 'Sellepärast, otsekui ühe inimese kaudu patt tuli maailma ja patu läbi surm, nõnda on ka surm tunginud kõigisse inimestesse, sest nad kõik on pattu teinud.',
        13: 'Sest patt oli maailmas ka enne käsku, kuid pattu ei arvata süüks seal, kus ei ole käsku.',
        14: 'Ometi valitses surm Aadamast Mooseseni ka neid, kes ei olnud pattu teinud samasuguse üleastumisega nagu Aadam, kes oli selle eeltähendus, kes pidi tulema.',
        15: 'Aga ka armuanniga ei ole lugu nõnda nagu pattulangemisega; sest kui ühe inimese pattulangemise läbi paljud on surnud, siis on veel palju enam Jumala arm ja and selle ühe Inimese Jeesuse Kristuse armu läbi ülirohkesti saanud osaks neile paljudele.',
        16: 'Ja ka anniga ei ole nõnda nagu sellega, mis on tulnud ühe pattulangenu läbi; sest ühest ainsast pattulangemisest on kohus saanud hukkamõistmiseks, aga armuand mitmest pattulangemisest õigeksmõistmiseks.',
        17: 'Sest kui ühe inimese pattulangemise tõttu surm on valitsenud selle ühe läbi, kui palju enam peavad need, kes saavad armu ja õiguse anni täiuse, valitsema elus selle ühe, Jeesuse Kristuse läbi.',
        18: 'Nõnda siis, otsekui üks langemine on saanud hukkamõistmiseks kõigile inimestele, nõnda saab ka üks õiguse täitmine kõigile inimestele elu õigustuseks.',
        19: 'Sest otsekui tolle ühe inimese sõnakuulmatuse läbi paljud on saanud patuseks, nõnda saavad ka selle ühe inimese sõnakuulelikkuse läbi paljud õigeks.',
        20: 'Aga käsk tuli kõrvalt sisse, et langemine saaks suuremaks. Ent kus patt on suurenenud, seal on ka arm saanud ülirohkeks,',
        21: 'et otsekui patt on valitsenud surmas, samuti ka arm valitseks õiguse kaudu igaveseks eluks Jeesuse Kristuse, meie Issanda läbi.',
    },
    6: {
        1: 'Mis me nüüd ütleme? Kas peame jääma patusse, et arm suureneks?',
        2: 'Ei milgi kombel! Meie, kes oleme ära surnud patule, kuidas peaksime veel elama selles?',
        3: 'Või te ei tea, et nii mitu, kui meid on ristitud Kristusesse Jeesusesse, oleme ristitud Tema surmasse?',
        4: 'Me oleme siis surmasse ristimise kaudu ühes Temaga maha maetud, et otsekui Kristus on surnuist üles äratatud Isa au läbi, nõnda meiegi käiksime uues elus.',
        5: 'Sest kui me oleme kasvanud ühte Tema surma sarnasusega, siis saame üheks ka Tema ülestõusmise sarnasusega,',
        6: 'kuna me seda teame, et meie vana inimene on ühes temaga risti löödud, et patuihu kaotataks, nõnda et me enam ei orjaks pattu;',
        7: 'sest kes on surnud, see on õigeks mõistetud patust.',
        8: 'Aga kui me ühes Kristusega oleme surnud, siis usume, et me ühes Temaga saame ka elama.',
        9: 'Sest me teame, et Kristus pärast seda, kui Ta surnuist üles äratati, enam ei sure; surm ei valitse enam Tema üle.',
        10: 'Sest mis Ta suri, seda Ta suri patule ühe korra; aga mis Ta elab, elab Ta Jumalale.',
        11: 'Nõnda arvake teiegi endid surnud olevat patule, aga elavat Jumalale Kristuses Jeesuses.',
        12: 'Seepärast ärgu valitsegu siis patt teie surelikus ihus, et te kuulaksite teda tema himudes.',
        13: 'Ärge ka mitte andke oma liikmeid ülekohtu relviks patule, vaid andke iseendid Jumalale kui need, kes surnuist on saanud elavaks, ja oma liikmed õiguse relviks Jumalale.',
        14: 'Sest patt ei tohi teie üle valitseda, sellepärast et teie ei ole käsu all, vaid armu all.',
        15: 'Kuidas siis? Kas hakkame pattu tegema, sest me ei ole käsu all, vaid armu all? Mitte sugugi!',
        16: 'Eks te tea, et kelle orjaks te hakkate sõnakuulmises, selle orjad te olete, kelle sõna te kuulete, kas patu orjad surmaks või sõnakuulmise orjad õiguseks?',
        17: 'Aga tänu Jumalale, et te olite patu orjad, aga nüüd olete südamest saanud sõnakuulelikuks sellele õpetuse väljendusele, mille juurde teid on juhatatud,',
        18: 'ja et te patust vabanenuina olete saanud õiguse orjadeks!',
        19: 'Ma räägin inimese kombel teie liha nõtruse pärast. Sest otsekui te oma liikmed andsite orjadeks rüvedusele ja ülekohtule, selleks et käsust üle astuda, nõnda andke nüüd oma liikmed õiguse orjadeks pühitsusele.',
        20: 'Sest kui te olite patu orjad, olite vabad õigusest.',
        21: 'Mis vilja te kandsite siis? Niisugust, millest teil nüüd on häbi! Sest selle lõpp on surm!',
        22: 'Aga nüüd, et te olete saanud patust vabaks ja Jumala orjadeks, on teie vili pühitsuseks ja selle lõpp on igavene elu.',
        23: 'Sest patu palk on surm, aga Jumala armuand on igavene elu Kristuses Jeesuses, meie Issandas!',
    },
    7: {
        1: 'Või eks te tea, vennad - mina räägin käsutundjaile - et käsk valitseb inimese üle, niikaua kui inimene elab.',
        2: 'Nii on abielunaine käsuga seotud elusoleva mehe külge; aga kui mees sureb, on ta lahti mehe käsu alt.',
        3: 'Sellepärast, kui naine mehe elus olles läheb teisele mehele, nimetatakse teda abielurikkujaks; aga kui mees sureb, on ta sellest käsust vaba, nii et ta ei ole abielurikkuja, kui ta läheb teisele mehele.',
        4: 'Nõnda teiegi, mu vennad, olete surmatud käsule Kristuse ihu läbi, et saaksite teisele mehele, kes on surnuist üles äratatud, et me kannaksime vilja Jumalale.',
        5: 'Sest kui me olime lihas, siis patuhimud, mis tõusid käsu läbi, tegutsesid meie liikmetes, et kanda vilja surmale.',
        6: 'Aga nüüd me oleme käsust lahti ning oleme surnud sellele, mis meid kinni pidas, nii et me teenime Jumalat vaimu uues olemises ja mitte kirjatähe vanas olemises.',
        7: 'Mis me siis ütleme? Ons käsk patt? Mitte sugugi! Ent pattu ma ei oleks tundnud muidu kui käsu kaudu; sest ma ei oleks kurjast himust midagi teadnud, kui käsk ei oleks öelnud: "Sa ei tohi himustada!"',
        8: 'Aga patt, saades tõuget käsust, äratas minus kõiksugu himusid; sest ilma käsuta on patt surnud.',
        9: 'Mina elasin enne ilma käsuta; aga kui käsusõna tuli, virgus patt ellu',
        10: 'ja mina surin ära, ja nõnda leiti käsusõna, mis mulle pidi olema eluks, mulle olevat surmaks.',
        11: 'Sest kui patt oli saanud käsusõnast tõuke, pettis ta mind ja surmas mind selle abil.',
        12: 'Nõnda on siis käsk püha ja käsusõna püha ja õige ja hea.',
        13: 'Kas siis nüüd see, mis on hea, on saanud mulle surmaks? Mitte sugugi! Vaid patt, et ta ilmneks patuna, on selle hea kaudu mulle toonud surma, et patt ise saaks üliväga patuseks käsusõna läbi.',
        14: 'Sest me teame, et käsk on vaimne, aga mina olen lihalik ja müüdud patu alla.',
        15: 'Ma ei tunne ju ära, mida ma teen; sest ma ei tee seda, mida ma tahan, vaid mida ma vihkan, seda ma teen.',
        16: 'Kui ma aga teen, mida ma ei taha, siis ma möönan, et käsk on hea.',
        17: 'Nii ei tee seda enam mitte mina, vaid patt, mis minus elab.',
        18: 'Sest ma tean, et minus, see on minu lihas, ei ela head. Tahet mul on, aga head teha ma ei suuda;',
        19: 'sest head, mida ma tahan, ma ei tee, vaid kurja, mida ma ei taha, ma teen!',
        20: 'Kui ma nüüd teen seda, mida ma ei taha, siis ei tee seda enam mitte mina, vaid patt, mis minus elab.',
        21: 'Nii ma leian eneses käsu, et kuigi ma tahan teha head, on mulle omane teha kurja.',
        22: 'Sest seespidise inimese poolest on mul Jumala käsust hea meel,',
        23: 'aga oma liikmetes ma tunnen teist käsku, mis paneb vastu mu mõistuse käsule ja võtab mind vangi patu käsu alla, mis on mu liikmetes.',
        24: 'Oh mind viletsat inimest! Kes päästab mind sellest surma ihust?',
        25: 'Tänu olgu Jumalale Jeesuse Kristuse, meie Issanda läbi! Nii ma siis teenin oma mõistusega Jumala käsku, aga lihaga patu käsku.',
    },
    8: {
        1: 'Nii ei ole siis nüüd mingisugust hukkamõistmist neile, kes on Kristuses Jeesuses.',
        2: 'Sest elu vaimu käsk Kristuses Jeesuses on sind vabastanud patu ja surma käsust.',
        3: 'Sest mis oli võimatu käsule, sellepärast et ta oli jõuetu liha tõttu, seda tegi Jumal, kui Ta läkitas Oma Poja patuse liha sarnasuses ja patu pärast ning mõistis patu hukka liha sees,',
        4: 'et käsu õigus täide viidaks meie sees, kes me ei käi liha järgi, vaid Vaimu järgi.',
        5: 'Sest kes elavad liha järgi, nende meel on suunatud lihalikele asjadele; aga kes elavad Vaimu järgi, neil vaimsetele asjadele.',
        6: 'Sest liha mõtteviis, see on surm, aga Vaimu mõtteviis, see on elu ja rahu,',
        7: 'sellepärast et liha mõtteviis on vaen Jumala vastu, sest ta ei alistu Jumala käsule ega võigi alistuda.',
        8: 'Kes siis lihameeles on, need ei või olla Jumalale meelepärased.',
        9: 'Aga teie ei ole lihameeles, vaid vaimus, kui Jumala Vaim tõepoolest asub teie sees. Aga kellel ei ole Kristuse Vaimu, see ei ole Tema Oma.',
        10: 'Kui aga Kristus on teie sees, siis on küll ihu surnud patu pärast; aga vaim on elu õiguse pärast.',
        11: 'Aga kui selle Vaim, kes Jeesuse on surnuist üles äratanud, teis elab, siis Tema, Kes Kristuse Jeesuse surnuist üles äratas, teeb ka teie surelikud ihud elavaks Oma Vaimu läbi, Kes teis elab.',
        12: 'Sellepärast nüüd, vennad, oleme küll võlglased, aga mitte lihale, et elada liha järgi.',
        13: 'Sest kui te liha järgi elate, siis te surete; aga kui te Vaimu läbi ihu teod suretate, siis te elate.',
        14: 'Sest kõik, keda iganes Jumala Vaim juhib, on Jumala lapsed.',
        15: 'Sest te ei ole saanud orjapõlve vaimu, et peaksite jälle kartma, vaid te olete saanud lapsepõlve Vaimu, kelles me hüüame: "Abba! Isa!"',
        16: 'Seesama Vaim tunnistab ühes meie vaimuga, et me oleme Jumala lapsed.',
        17: 'Kui me aga oleme lapsed, siis oleme ka pärijad, nii Jumala pärijad kui ka Kristuse kaaspärijad, et kui me ühes Temaga kannatame, siis meid ühes Temaga ka austatakse.',
        18: 'Sest ma arvan, et selle aja kannatused ei ole midagi tulevase au vastu, mis meile peab ilmsiks saama.',
        19: 'Sest kogu loodu ootab pikisilmi Jumala laste ilmsikssaamist.',
        20: 'On ju kogu loodu heidetud kaduvuse alla - mitte vabatahtlikult, vaid allaheitja tahtest - ometi lootuse peale,',
        21: 'sest ka kogu loodu ise päästetakse kord kaduvuse orjusest Jumala laste au vabadusse.',
        22: 'Sest me teame, et kõik loodu ühtlasi ägab ja on aina sünnitusvaevas tänini;',
        23: 'aga mitte üksnes seda, vaid isegi need, kellel on Vaimu esmaand, ka meie ise ägame enestes ning ootame lapseseisust, oma ihu lunastust.',
        24: 'Sest me oleme päästetud lootuses. Ent lootus, mida nähakse, ei ole mingi lootus; sest mida keegi näeb, kuidas ta seda veel loodab?',
        25: 'Aga kui me loodame seda, mida me ei näe, siis me ootame seda kannatlikkusega.',
        26: 'Aga samuti tuleb ka Vaim appi meie nõtrusele; sest me ei tea seda, mida paluda, nõnda nagu peaks, ent Vaim Ise palvetab meie eest sõnades väljendamatute ohkamistega.',
        27: 'Aga südamete uurija teab, mis Vaimul on mõttes, et Ta kooskõlas Jumalaga kostab pühade eest.',
        28: 'Aga me teame, et neile, kes Jumalat armastavad, kõik ühtlasi heaks tuleb, neile, kes Tema kavatsuse järgi on kutsutud.',
        29: 'Sest keda Ta on ette ära tundnud, need on Ta ka ette ära määranud olema Tema Poja näo sarnased, et Tema oleks esmasündinu paljude vendade seas.',
        30: 'Aga keda Ta on ette ära määranud, need on Ta ka kutsunud, ja keda Ta on kutsunud, need on Ta ka õigeks teinud, ent keda Ta on õigeks teinud, neid on Ta ka austanud.',
        31: 'Mis me siis ütleme selle kohta? Kui Jumal on meie poolt, kes võib olla meie vastu?',
        32: 'Tema, Kes Oma Poegagi ei säästnud, vaid loovutas Tema meie kõikide eest, kuidas Ta ei peaks siis Temaga meile kõike muud annetama?',
        33: 'Kes võib süüdistada Jumala valituid? Jumal on, Kes õigeks teeb.',
        34: 'Kes on, kes võib hukka mõista? Kristus Jeesus on, Kes suri, ja mis veel enam, Kes üles äratati, Kes on Jumala paremal käel, Kes meie eest palub.',
        35: 'Kes võib meid lahutada Kristuse armastusest? Kas viletsus, või ahastus, või tagakiusamine, või nälg, või alastiolek, või häda, või mõõk?',
        36: 'Nõnda nagu on kirjutatud: "Sinu pärast surmatakse meid kogu päev, meid arvatakse tapalambaiks!"',
        37: 'Aga selles kõiges me saame täie võidu Tema läbi, Kes meid on armastanud!',
        38: 'Sest ma olen veendunud selles, et ei surm ega elu, ei Inglid, ei vürstid, ei käesolev ega tulev, ei vägevad,',
        39: 'ei kõrgus ega sügavus ega mingi muu loodu või meid lahutada Jumala armastusest, mis on Kristuses Jeesuses, meie Issandas!',
    },
    9: {
        1: 'Ma räägin tõtt Kristuses, mina ei valeta mitte; seda tunnistab mulle mu südametunnistus Pühas Vaimus,',
        2: 'et mul on suur kurbus ja lõpmatu valu mu südames.',
        3: 'Sest ma sooviksin ise saada äraneetavaks, Kristusest lahku oma vendade heaks, kes on mu sugulased liha poolest,',
        4: 'kes on iisraellased, kellele kuuluvad lapseõigus ja au, ja lepingud ja käsuandmine, ja jumalateenistus ja tõotused,',
        5: 'kelle omad on esiisad ja kellest Kristus on pärit liha poolest, Tema, Kes on Jumal üle kõige, kiidetud igavesti! Aamen.',
        6: 'Aga ei või olla nõnda, et Jumala sõna oleks läinud tühja; sest mitte kõik need, kes põlvnevad Iisraelist, ei ole Iisrael;',
        7: 'ka ei ole kõik lapsed selle tõttu, et nad on Aabrahami sugu, vaid on öeldud: "Iisakist loetakse sinu sugu!"',
        8: 'See on: lihased lapsed, mitte need ei ole Jumala lapsed, vaid tõotuse lapsed arvatakse sooks.',
        9: 'Sest tõotuse sõna on see: "Ma tulen jälle aasta pärast samal ajal, ja Saaral saab olema poeg!"',
        10: 'Aga mitte ainult temaga, vaid ka Rebekaga oli samane lugu, kui ta ühest, see on meie esiisast Iisakist, sai käima peale.',
        11: 'Sest enne kui kaksikud olid sündinud ega olnud teinud midagi head ega halba, siis - selleks, et valikule vastav Jumala otsustus jääks kindlaks mitte tegude pärast, vaid kutsuja tõttu -',
        12: 'öeldi temale: "Vanem orjab nooremat!",',
        13: 'nagu ju on kirjutatud: "Jaakobit Ma armastasin, aga Eesavit Ma vihkasin!"',
        14: 'Mida me nüüd ütleme? Kas Jumal teeb ülekohut? Mitte sugugi!',
        15: 'Sest Ta ütleb Moosesele: "Ma olen armuline, kellele Ma olen armuline, ja halastan, kelle peale Ma halastan!"',
        16: 'Nõnda siis ei olene see sellest, kes tahab, ega sellest, kes jookseb, vaid Jumalast, kes armu annab.',
        17: 'Sest Kiri ütleb vaaraole: "Just selleks Ma olen sind õhutanud, et sinus näidata Oma väge ja teha kuulsaks Oma nime kogu maailmas!"',
        18: 'Nõnda Ta siis annab armu, kellele tahab, ja paadutab, keda tahab.',
        19: 'Sa ehk ütled nüüd mulle: "Miks Ta siis veel sõitleb? Kes võib vastu panna Tema tahtele?"',
        20: 'Oh inimene, nii see on! Kes siis sina oled, et sa tahad vaielda Jumala vastu? Kas see, mis tehtud, ütleb oma tegijale: "Miks sa mu nõnda tegid?"',
        21: 'Või ei ole potissepal meelevalda savi ühest ja samast segust teha ühe astja õilsaks, teise halvaks otstarbeks?',
        22: 'Eks Jumal, tahtes osutada Oma viha ja teha teatavaks Oma väge, suure pikameelega sallinud vihaastjaid, mis olid valmistatud hukatuseks,',
        23: 'ja teinud seda selleks, et ilmutada Oma au rikkust armuastjate vastu, mis Ta ette oli valmistanud aulisteks,',
        24: 'nõnda nagu Tema on kutsunud ka meid, mitte ainult juutide, vaid ka paganate seast?',
        25: 'Nõnda nagu Ta ütleb ka Hoosea raamatus: "Ma tahan hüüda Omaks rahvaks neid, kes ei olnud Mu rahvas, ja Oma armsaks seda, kes ei olnud Mulle armas;',
        26: 'ja sünnib, et seal paigas, kus neile öeldi: teie ei ole Minu rahvas! hüütakse neid elava Jumala lasteks!"',
        27: 'Aga Jesaja hüüab Iisraeli kohta: "Kuigi Iisraeli laste arv oleks otsekui mereliiv, pääseb sellest ainult jääk;',
        28: 'sest lõplikult ja kiiresti teostab Issand Oma sõna maa peal!"',
        29: 'Ja nõnda nagu Jesaja on ette öelnud: "Kui mitte vägede Issand ei oleks meile jätnud seemet, oleksime olnud nagu Soodom ja saanud Gomorra sarnaseks!"',
        30: 'Mis me siis nüüd ütleme? Seda, et paganad, kes õigust ei taotlenud, on kätte saanud õiguse, ent õiguse, mis tuleb usust.',
        31: 'Aga Iisrael, kes taotles õiguse käsku, ei ole käsku kätte saanud!',
        32: 'Mispärast? Sellepärast et taotlus ei olnud usust, vaid otsekui tegudest; nad tõukasid endid vastu komistuskivi,',
        33: 'nõnda nagu on kirjutatud: "Vaata, Ma panen Siionisse komistuskivi ja pahanduskalju; ja kes usub Temasse, ei jää häbisse!"',
    },
    10: {
        1: 'Vennad, minu südame hea meel ja palve Jumala poole nende eest on, et nad õndsaks saaksid!',
        2: 'Sest ma annan neile tunnistuse, et nad on väga agarad Jumala suhtes, kuid mitte õiget tunnetust mööda;',
        3: 'sest kui nad ei mõista Jumala õigust ja püüavad üles seada oma õigust, siis ei ole nad alistunud Jumala õigusele.',
        4: 'Sest käsu lõppsiht on Kristus õiguseks igaühele, kes usub.',
        5: 'Sest Mooses kirjutab õigusest, mis tuleb käsust, et inimene, kes seda täidab, elab sellest.',
        6: 'Aga õigus, mis tuleb usust, ütleb nõnda: "Ära ütle oma südames: kes läheb üles taevasse? See on: Kristust alla tooma;',
        7: 'või: kes läheb alla sügavusse? See on: Kristust surnuist üles tooma!"',
        8: 'Vaid mis ta ütleb? "Sõna on sinule ligidal, sinu suus ja sinu südames!" See on usu sõna, mida me kuulutame!',
        9: 'Sest kui sa oma suuga tunnistad, et Jeesus on Issand, ja oma südames usud, et Jumal on Tema surnuist üles äratanud, siis sa saad õndsaks!',
        10: 'Sest südamega usutakse õiguseks, ent suuga tunnistatakse õndsuseks.',
        11: 'Sest Kiri ütleb: "Ükski, kes Temasse usub, ei jää häbisse!"',
        12: 'Siin ei ole vahet juudi ja kreeklase vahel, sest üks ja sama on kõikide Issand, rikas kõikide heaks, kes Teda appi hüüavad.',
        13: 'Sest igaüks, kes hüüab appi Issanda nime, päästetakse.',
        14: 'Kuidas nad nüüd saavad appi hüüda Teda, Kellesse nad ei ole uskunud? Ja kuidas nad võivad uskuda Temasse, kellest nad ei ole kuulnud? Ja kuidas nad saavad kuulda ilma kuulutajata?',
        15: 'Ja kuidas nad võivad kuulutada, kui neid ei läkitata? Nõnda nagu on kirjutatud: "Kui armsad on nende sammud, kes häid sõnumeid kuulutavad!"',
        16: 'Aga mitte kõik ei ole võtnud kuulda Evangeeliumi sõna. Sest Jesaja ütleb: "Issand, kes usub meie kuulutust?"',
        17: 'Nii tuleb siis usk kuuldust, aga kuuldu Kristuse sõna kaudu.',
        18: 'Aga ma küsin: kas nad siis ei ole kuulnud? On küll! "Üle kogu ilmamaa käib nende hääl ja maailma otsteni nende sõna!"',
        19: 'Aga ma küsin: kas Iisrael ei ole teada saanud? Esimesena ütleb Mooses: "Mina ärritan teid rahvaga, kes ei ole rahvas, ja vihastan teid mõistmatu rahvaga!"',
        20: 'Ent Jesaja räägib julgesti ja ütleb: "Mind on leidnud need, kes mind ei ole otsinud; ma olen saanud ilmsiks neile, kes mind ei ole nõudnud!"',
        21: 'Aga Iisraeli kohta ta ütleb: "Kogu päeva ma sirutan käsi rahva poole, kes ei kuula sõna ja räägib vastu!"',
    },
    11: {
        1: 'Siis ma nüüd ütlen: kas vahest Jumal on Oma rahva hüljanud? Mitte sugugi! Sest minagi olen Iisraeli mees, Aabrahami soost, Benjamini suguharust.',
        2: 'Jumal ei ole hüljanud Oma rahvast, kelle Tema on ette ära tundnud. Või kas te ei tea, mis Kiri ütleb Eelijast, kuidas tema Jumala ees kaebab Iisraeli pärast, öeldes:',
        3: '"Issand, Sinu prohvetid on nad tapnud ja Sinu altarid maha kiskunud, ja mina olen üksi üle jäänud, ja nemad tahavad võtta mu elu!"',
        4: 'Aga mis ütleb temale Jumala vastus? "Mina olen Enesele üle jätnud seitse tuhat meest, kes ei ole nõtkutanud põlvi Baali ees!"',
        5: 'Samuti on ka siis praegusel ajal jääk üle jäänud armuvalikut mööda.',
        6: 'Aga kui see on armust, siis ei ole see enam tegudest; muidu arm ei oleks arm. Aga kui see on tegudest, siis ei ole see enam arm; muidu tegu ei oleks enam tegu.',
        7: 'Mis nüüd? Mida Iisrael taotleb, seda ta ei ole saavutanud; ent äravalitud on selle saavutanud ja teised on paadunud,',
        8: 'nõnda nagu on kirjutatud: "Jumal on neile andnud uimuse vaimu, silmad mitte nägema ja kõrvad mitte kuulma tänapäevani!"',
        9: 'Ja Taavet ütleb: "Nende laud saagu neile püüdepaelaks ja lõksuks ja pahanduseks ja kättemaksuks!',
        10: 'Nende silmad saagu pimedaks, et nad ei näeks, ja murra nende selg kõveraks jäädavalt!"',
        11: 'Ma ütlen nüüd: ega nad ole komistanud selleks, et langeda? Ei sugugi mitte! Vaid nende eksimise läbi tuleb pääste paganaile, et paganad teeksid neid kadedaks.',
        12: 'Aga kui nende eksimine on maailma rikkus ja nende kahju paganate rikkus, saati siis nende täisarv!',
        13: 'Mina aga kõnelen teile, paganaile! Sest sedavõrd kui ma olen paganate Apostel, austan ma oma ametit,',
        14: 'et võiksin kuidagi õhutada neid, kes on mu liha ja veri, ja mõned nende seast päästa.',
        15: 'Sest kui juba nende hülgamine on maailma lepitus, mis on siis nende vastuvõtt muud kui surnuist ellusaamine?',
        16: 'Aga kui uudsevili on püha, siis on ka taigen püha; ja kui juur on püha, siis on ka oksad pühad.',
        17: 'Kui nüüd okstest mõned on ära murtud ja sina, kes olid metsõlipuu, oled jätkatud nende asemele ja oled ühes nendega osa saanud õlipuu mahlakast juurest,',
        18: 'siis ära kiitle okste vastu. Ja kui sa kiitled, siis mõtle, et sina ei kanna juurt, vaid juur kannab sind.',
        19: 'Sina ehk ütled nüüd: "Oksad on ära murtud, et mind külge jätkataks!"',
        20: 'Õige küll! Uskmatuse pärast on nad ära murtud; aga sina püsid usu läbi. Ära saa omas meeles suureliseks, vaid karda!',
        21: 'Sest kui Jumal ei säästnud loodud oksi, ega Ta sindki säästa!',
        22: 'Sellepärast vaata Jumala heldust ja valjust; valjust küll nende vastu, kes on langenud; aga heldust sinu vastu, kui sa püsid helduses, muidu sindki raiutakse maha!',
        23: 'Aga nemadki, kui nad ei jää uskmatusse, jätkatakse puu külge; sest Jumal võib nad jälle külge jätkata.',
        24: 'Sest kui sina loomulikust metsõlipuust oled ära lõigatud ja loomu vastu oled jätkatud väärisõlipuu külge, saati siis, et nemad kui loodud oksad, jätkatakse iseeneste õlipuu külge.',
        25: 'Sest mina ei taha, vennad, et teile jääks teadmatuks see saladus - et teie ei oleks eneste meelest targad - et Iisraelile osalt on tulnud paadumus, kuni paganate täisarv on läinud sisse,',
        26: 'ja kogu Iisrael päästetakse, nõnda nagu on kirjutatud: "Siionist tuleb Päästja ja kõrvaldab Jaakobist jumalatuse.',
        27: 'Ja see on Minu leping nendega, kui Ma ära võtan nende patud!"',
        28: 'Evangeeliumi poolest on nad küll vaenlased teie pärast, aga valiku poolest on nad armastatud esiisade pärast.',
        29: 'Sest Jumal ei võta tagasi Oma armuande ja kutsumist!',
        30: 'Sest otsekui teie muiste olite Jumalale sõnakuulmatud, aga nüüd olete armu saanud nende sõnakuulmatuse läbi,',
        31: 'nõnda on nüüd ka nemad sõnakuulmatud, et ka nemad nüüd teile osaks saanud armu kaudu saaksid armu.',
        32: 'Sest Jumal on kõik inimesed kinni pannud sõnakuulmatuse alla, et Ta armu annaks kõikidele.',
        33: 'Oh seda Jumala rikkuse ja tarkuse ja tunnetuse sügavust! Kui väljauurimatud on Tema kohtumõistmised ja äraarvamatud Tema teed!',
        34: 'Sest kes on ära tundnud Issanda meele? Või kes on olnud Tema nõuandja?',
        35: 'Või kes on Temale midagi enne andnud, et Temale peaks jälle tasutama?',
        36: 'Sest Tema seest ja Tema läbi ja Tema poole on kõik asjad. Temale olgu au igavesti! Aamen.',
    },
    12: {
        1: 'Mina manitsen teid nüüd, vennad, Jumala suure südamliku halastuse tõttu andma oma ihud elavaks pühaks ja Jumala meelepäraseks ohvriks. See olgu teie mõistlik jumalateenistus.',
        2: 'Ja ärge saage selle maailma sarnaseks, vaid muutuge teiseks oma meele uuendamise teel, et te uuriksite, mis on Jumala hea ja meelepärane ja täielik tahtmine.',
        3: 'Sest selle armu läbi, mis mulle on antud, ma ütlen teile igaühele, et ta ei mõtleks üleolevalt selle kohta, mida tuleb mõelda, vaid mõtleks nõnda, et saaks arukaks sedamööda, kuidas Jumal igaühele usu mõõdu on jaganud.',
        4: 'Sest otsekui meil ühes ihus on palju liikmeid, aga kõigil liikmeil ei ole sama töö,',
        5: 'nõnda oleme meiegi paljud üks ihu Kristuses, aga üksikult igaüks üksteise liikmed.',
        6: 'Aga meil on armu mööda, mis meile antud, mõnesuguseid armuandeid: olgu prohvetliku kuulutamise anne, mis toimugu usu mõõtu mööda;',
        7: 'olgu hoolekanne, mis toimugu hoolekandeametis; olgu keegi õpetaja, siis toimigu ta õpetamisametis;',
        8: 'manitseb keegi, siis ta olgu manitsemisametis; kes teistele annetab, andku siira südamega; kes teisi juhatab, olgu hoolas; kes vaeseid hooldab, tehku seda rõõmuga.',
        9: 'Armastus ärgu olgu silmakirjalik. Hoiduge kurjast eemale, kiinduge heasse!',
        10: 'Olge vennaarmastuse poolest hellasüdamelised üksteise vastu; vastastikuses austamises jõudke üksteisest ette!',
        11: 'Ärge olge viitsimatud hoolsuses; olge tulised vaimus; teenige Issandat!',
        12: 'Olge rõõmsad lootuses, kannatlikud ahastuses, püsivad palves!',
        13: 'Võtke osa pühade puudusest; püüdke olla külalislahked.',
        14: 'Õnnistage neid, kes teid taga kiusavad! Õnnistage ja ärge needke!',
        15: 'Olge rõõmsad rõõmsatega, nutke nutjatega!',
        16: 'Mõtelge ühesuguselt üksteise suhtes! Ärge nõudke kõrgeid asju, vaid hoiduge madaluse poole; ärge olge eneste meelest targad!',
        17: 'Ärge tasuge ühelegi kurja kurjaga; mõtelge ikka sellele, mis hea on kõigi inimeste suhtes!',
        18: 'Kui võimalik on ja niipalju kui teist oleneb, pidage rahu kõigi inimestega.',
        19: 'Ärge makske ise kätte, armsad, vaid andke maad Jumala vihale, sest on kirjutatud: "Minu käes on kättemaks, Mina tasun kätte! ütleb Issand."',
        20: '"Kui nüüd sinu vaenlasel on nälg, sööda teda; kui tal on janu, jooda teda; sest seda tehes sa kogud tuliseid süsi tema pea peale!"',
        21: 'Ära lase kurjal võitu saada enese üle, vaid võida sina kuri ära heaga!',
    },
    13: {
        1: 'Iga hing olgu allaheitlik valitsemas olevaile ülemustele; sest ülemust ei ole muud kui Jumalalt; kus neid on, seal on nad Jumala poolt seatud.',
        2: 'Kes nüüd ülemusele vastu paneb, see paneb vastu Jumala korrale; aga kes vastu panevad, saadavad eneste peale nuhtluse.',
        3: 'Sest valitsejad ei ole hirmuks headele tegudele, vaid kurjadele. Kui sina aga ei taha tunda hirmu ülemuse ees, siis tee head, ja siis sa saad temalt kiitust.',
        4: 'Sest tema on Jumala teener sinu heaks; aga kui sa kurja teed, karda, sest ta ei kanna mõõka asjata; ta on Jumala teenija, kättemaksja nuhtluseks sellele, kes kurja teeb.',
        5: 'Siis on tarvis olla allaheitlik, mitte ainult nuhtluse, vaid ka südametunnistuse pärast.',
        6: 'Sellepärast makske ka makse; sest nemad on Jumala sulased, kes selleks peavad oma ametit.',
        7: 'Tasuge kõigile, mis teie kohus on: maksu, kellele maksu; tolliraha, kellele tolliraha; kartust, kellele kartust; au, kellele au tuleb anda!',
        8: 'Ärgu olgu teil midagi kellegagi võlgu, kui et te üksteist armastate, sest kes teist armastab, on käsu täitnud.',
        9: 'Sest käsk: "Sa ei tohi abielu rikkuda; sa ei tohi tappa; sa ei tohi varastada; sa ei tohi ülekohut tunnistada; sa ei tohi himustada", ja iga teine käsk on kokku võetud sellesse sõnasse: "Armasta oma ligimest nagu iseennast!"',
        10: 'Armastus ei tee ligimesele kurja; siis on armastus käsu täitmine.',
        11: 'Ja seda tehke sellepärast et te teate tunni juba käes olevat unest üles ärgata; sest nüüd on meie pääste lähemal kui siis, kui me usklikuks saime.',
        12: 'Öö on möödumas, aga päev on lähedal. Siis heitkem enestest ära pimeduse teod ja varustugem valguse relvadega!',
        13: 'Elagem ausasti nagu päeva ajal, mitte öistes pidutsemistes ega joominguis, mitte kiimaluses ega iharuses, mitte riius ega kadeduses,',
        14: 'vaid varustuge Issanda Jeesuse Kristusega ja ärge muutke liha eest hoolitsemist himude ärritamiseks!',
    },
    14: {
        1: 'Usu poolest nõrgale olge vastutulelikud ilma vaidlust alustamata arvamiste kohta.',
        2: 'Mõni usub, et ta võib süüa kõike, aga kes on nõrk, sööb taimetoitu.',
        3: 'Kes sööb, ärgu pidagu halvaks seda, kes mitte ei söö; ja kes ei söö, ärgu mõistku hukka seda, kes sööb; sest Jumal on tema vastu võtnud.',
        4: 'Kes oled sina, et sa mõistad hukka teise sulase? Tema seisab või langeb iseenese isandale. Aga tema jääb seisma, sest Jumal võib teda püsti hoida.',
        5: 'Mõni arvab üht päeva paremaks teisest, aga teine peab kõik päevad ühesuguseks. Igaüks olgu enese mõttes kindel omas veendumuses.',
        6: 'Kes paneb tähele päeva, paneb seda tähele Issandale; ja kes sööb, sööb Issandale, sest tema tänab Jumalat; ja kes mitte ei söö, jääb söömata Issandale ning tänab Jumalat.',
        7: 'Sest keegi meist ei ela iseenesele ja keegi meist ei sure iseenesele.',
        8: 'Sest kui me elame, siis elame Issandale, ja kui me sureme, siis sureme Issandale. Kas me siis elame või sureme, oleme Issanda Omad!',
        9: 'Sest Kristus suri selleks ja sai jälle elavaks, et Ta oleks nii surnute kui ka elavate Issand.',
        10: 'Aga sina, miks sa mõistad kohut oma venna üle? Või sina teine, miks sa paned oma venda halvaks? Meid kõiki ju seatakse Jumala kohtujärje ette.',
        11: 'Sest on kirjutatud: "Nii tõesti kui Ma elan, ütleb Issand, Minu ees peab nõtkuma iga põlv ja iga keel peab tunnistama Jumalat!"',
        12: 'Nõnda tuleb meil igaühel anda aru iseenesest Jumalale.',
        13: 'Ärgem siis enam mõistkem kohut üksteise üle, vaid pigemini otsustagem hoiduda saamast vennale komistuseks ja pahanduseks.',
        14: 'Ma tean ja olen veendunud Issandas Jeesuses, et midagi ei ole ebapüha iseenesest, vaid on ebapüha üksnes sellele, kes midagi peab ebapühaks.',
        15: 'Aga kui sinu vend saab nukraks roa pärast, siis ei käi sina enam armastuse järgi. Ära saada hukka oma roaga seda, kelle eest Kristus on surnud.',
        16: 'Sellepärast ärgu saagu hea, mis teil on, pilgatavaks.',
        17: 'Sest Jumala riik ei ole mitte söömine ega joomine, vaid õigus ja rahu ja rõõm Pühas Vaimus.',
        18: 'Sest kes neis asjus orjab Kristust, see on Jumalale meelepärane ja kõlvuline inimestele.',
        19: 'Siis taotlegem nüüd seda, mis läheb tarvis rahuks ja vastastikuseks paranduseks.',
        20: 'Ära riku roa pärast Jumala teost! Kõik on küll puhas, aga paha on see sellele inimesele, kes sööb pahandusega.',
        21: 'Hea on liha mitte süüa ja viina mitte juua, ja mitte teha seda, mis su vennale on komistuseks.',
        22: 'Usk, mis sul on, pea enesele Jumala ees. Õnnis on see, kes iseennast ei mõista hukka selles, mida ta peab õigeks;',
        23: 'aga kui keegi kõheldes sööb, siis on ta hukka mõistetud, sest see ei tule usust. Aga kõik, mis ei ole usust, on patt!',
    },
    15: {
        1: 'Aga meie, kes oleme tugevad, peame kandma jõuetute nõrkusi ega tohi elada iseeneste meele heaks.',
        2: 'Igaüks meist olgu ligimesele meelepärane tema heaks, et teda parandada.',
        3: 'Sest Kristuski ei elanud Enese meele heaks, vaid nõnda nagu on kirjutatud: "Nende teotamised, kes Sind teotavad, on langenud Minu peale!"',
        4: 'Sest mis iganes enne on kirjutatud, on kirjutatud meile õpetuseks, et meil kannatlikkuse ja Kirja troosti kaudu oleks lootust.',
        5: 'Aga kannatlikkuse ja troosti Jumal andku teile üksmeelt isekeskis Kristuse Jeesuse järele,',
        6: 'et te ühel meelel ja ühe suuga austaksite Jumalat ja meie Issanda Jeesuse Kristuse Isa!',
        7: 'Sellepärast võtke vastu üksteist, nõnda nagu ka Kristus teid on vastu võtnud Jumala austuseks.',
        8: 'Sest ma ütlen, et Jeesus Kristus sai ümberlõikamise sulaseks Jumala tõe pärast, et kinnitada isadele antud tõotused,',
        9: 'aga et paganad ülistavad Jumalat Tema halastuse pärast, nõnda nagu on kirjutatud: "Sellepärast ma tahan Sind ülistada paganate seas ja laulda kiitust Su nimele!"',
        10: 'Ja taas ütleb tema: "Olge rõõmsad, paganad, ühes Tema rahvaga!"',
        11: 'Ja veel: "Kiitke Issandat, kõik paganad, ja ülistage Teda, kõik rahvad!"',
        12: 'Ja jälle ütleb Jesaja: "Jesse juur tuleb ja see, kes tõuseb valitsema paganrahvaid; Tema peale hakkavad paganad lootma!"',
        13: 'Aga lootuse Jumal täitku teid kõige rõõmu ja rahuga usus, et teil oleks rohkesti lootust Püha Vaimu väes!',
        14: 'Mu vennad, mina isiklikult olen teie suhtes veendunud selles, et teie isegi olete täis headust, täidetud kõige teadmisega ning võite küll juhatada üksteist.',
        15: 'Ometi olen ma üsna julgesti mõnd teile kirjutanud, vennad, otsekui teile meeldetuletuseks, selle armu pärast, mille Jumal mulle on andnud selleks,',
        16: 'et ma oleksin Jeesuse Kristuse teenija paganate seas ja toimetaksin Jumala Evangeeliumi püha teenistust, et paganad saaksid meelepäraseks ja Pühas Vaimus pühitsetud ohvriannetuseks.',
        17: 'Sellepärast ma tohin Kristuses Jeesuses kiidelda Jumala asjust.',
        18: 'Sest mina ei julge kõnelda millestki muust kui sellest, mis Kristus minu läbi paganate sõnakuulelikuks tegemiseks on korda saatnud sõna ja teoga',
        19: 'tunnustähtede ja imetegude väel, Püha Vaimu väel, nõnda et mina Jeruusalemmast ja selle ümberkaudsest maast alates Illürikonini olen täide viinud Kristuse Evangeeliumi kuulutamise;',
        20: 'kuna ma nõnda olen pidanud oma auks armuõpetust mitte kuulutada seal, kus Kristust juba on nimetatud, et ma ei ehitaks teiste rajatud alusele,',
        21: 'vaid nõnda nagu on kirjutatud: "Need, kellele ei ole Temast midagi kuulutatud, saavad näha, ja need, kes ei ole kuulnud, mõistavad!"',
        22: 'See ongi see, mis mind mitu korda on takistanud teie juurde tulemast.',
        23: 'Aga et mul nüüd ei ole neis paigus enam aset ja et ma nii mitu aastat väga olen igatsenud teie juurde tulla,',
        24: 'siis ma ehk Hispaaniasse minnes tulen teie juurde, sest ma loodan teie kaudu matkates näha teid ja teie saatel jõuda sinna, niipea kui ma enne teie keskel ennast olen pisut rõõmustanud.',
        25: 'Aga nüüd ma lähen Jeruusalemma püha rahvast abistama.',
        26: 'Sest Makedoonia ja Ahhaia on heaks arvanud toime panna korjanduse neile, kes Jeruusalemmas elavate seas kehvad on.',
        27: 'Nemad on seda heaks arvanud ja nad on ka nende võlglased. Sest kui paganad on osa saanud nende vaimulikest andidest, siis on ka nende kohus neid aidata ihulike andidega.',
        28: 'Kui ma siis selle asja olen toimetanud ja neile selle saavutuse ustavalt kätte saatnud, tahan ma teie kaudu minna Hispaaniasse.',
        29: 'Aga ma tean, kui ma teie juurde tulen, et ma siis tulen Kristuse täie õnnistusega.',
        30: 'Ent mina manitsen teid, vennad, meie Issanda Jeesuse Kristuse läbi ja Vaimu armastuse läbi, minuga ühes võidelda eestpalvetega minu eest Jumala poole,',
        31: 'et ma pääseksin uskmatu rahva käest Juudamaal ja et minu abistus Jeruusalemma heaks oleks armas pühade meelest,',
        32: 'et ma Jumala tahtel võiksin rõõmuga tulla teie juurde ja teie keskel leida kosutust.',
        33: 'Aga rahu Jumal olgu teie kõikidega! Aamen.',
    },
    16: {
        1: 'Mina annan teie hooleks meie õe Foibe, kes on Kenkrea koguduse käsiline,',
        2: 'et te võtaksite teda vastu Issandas, nõnda nagu sobib pühadele, ja oleksite temale abiks kõiges, milles temal iganes teid on vaja. Sest tema on abiks olnud paljudele, ka mulle enesele.',
        3: 'Tervitage minu kaastöölisi Kristuses Jeesuses, Priskat ja Akvilat,',
        4: 'kes minu elu eest on pannud oma kaela tapavalmis, keda ei täna mitte mina üksi, vaid ka kõik paganate kogudused,',
        5: 'ja kogudust nende majas. Tervitage Epainetost, minu armast, kes oli esimene Aasias pöörduma Kristuse poole.',
        6: 'Tervitage Maarjat, kes on palju vaeva näinud teie eest.',
        7: 'Tervitage Andronikost ja Juuniust, minu sugulasi ja kaasvange, kes on kuulsad Apostlite hulgas ja kes enne mind on olnud Kristuses.',
        8: 'Tervitage Ampliatost, mu armast Issandas.',
        9: 'Tervitage Urbanust, meie kaastöölist Kristuses, ja mu armast Stahhüst.',
        10: 'Tervitage Apellest, kes on läbi katsutud Kristuses. Tervitage Aristobulose perekonda.',
        11: 'Tervitage Heroodioni, minu sugulast. Tervitage Narkissose perekonna liikmeid, kes on Issandas.',
        12: 'Tervitage Trüfainat ja Trüfoosat, kes teevad tööd Issandas. Tervitage Persist, armast õde, kes on näinud palju vaeva Issandas.',
        13: 'Tervitage Ruufust, Issandas äravalitut, ja tema ema, kes on ka minu ema.',
        14: 'Tervitage Asünkritost, Flegonit, Hermest, Patrobast, Hermast ja vendi, kes on nende juures.',
        15: 'Tervitage Filologost ja Juuliat, Neereust ja tema õde ja Olümpat ja kõiki pühasid, kes on nende juures.',
        16: 'Tervitage üksteist püha suudlusega. Kõik Kristuse kogudused tervitavad teid.',
        17: 'Aga mina manitsen teid, vennad, pidama silmas neid, kes tekitavad lõhesid ja pahandust õpetuse vastu, mis te olete õppinud, ja tõmbuge neist tagasi.',
        18: 'Sest niisugused inimesed ei teeni mitte meie Issandat Jeesust, vaid oma kõhtu, ja petavad magusate sõnadega ja libedate kõnedega tõemeelsete südameid.',
        19: 'Sest teie sõnakuulmine on saanud kõigile teatavaks; seepärast ma rõõmustun teist, kuid tahan, et teie oleksite targad heale, aga kohtlased pahale.',
        20: 'Aga rahu Jumal tallab varsti saatana teie jalge alla. Meie Issanda Jeesuse Kristuse arm olgu teiega! Aamen.',
        21: 'Teid tervitavad Timoteos, minu kaastööline, ja Luukius ja Jaason ja Sosipatros, minu sugulased.',
        22: 'Mina, Tertius, kes ma selle kirja olen kirjutanud, tervitan teid Issandas.',
        23: 'Teid tervitab Gaajus, kes on olnud külalislahke minule ja kõigele kogudusele. Teid tervitab Erastos, linna laekur, ja vend Kvartus.',
        24: 'Meie Issanda Jeesuse Kristuse arm olgu teie kõikidega! Aamen.',
        25: 'Ent sellele, kes teid võib kinnitada minu Evangeeliumi ja Jeesuse Kristuse jutluse järgi selle saladuse ilmutust mööda, mis on olnud igavesest ajast varjul,',
        26: 'aga nüüd on saanud avalikuks ja on prohvetite kirjade kaudu igavese Jumala käsul tehtud teatavaks kõigile rahvastele usu sõnakuulelikkuse saavutamiseks -',
        27: 'ainsale targale Jumalale, Jeesuse Kristuse läbi, Temale olgu au ajastute ajastuteni! Aamen.',
    },
}
